import test from 'node:test';
import assert from 'node:assert/strict';
import {correctProductData} from './product-title-corrections.mjs';
const rows=[{id:'9MH0XlaLQuIqWe1dlAHz',titulo:'Creatina Monohidratada 250g Growth Supplements - Sem sabor em Pó 100%',listing:'MLB5872060016'},{id:'9mrh9VQEs49ewAlruh38',titulo:'COLÁGENO TIPO 2 com 45mg - Fórmula Exclusiva para a Articulação com Máxima Concentração e Biodisponibilidade - 60 Cápsulas',listing:'MLB3909103951'},{id:'AF2AykzSppuQzGXdmvlT',titulo:'Kit 10 Pote De Vidro Marmita Hermético 370ml Freezer Fitness Rishon',listing:'MLB4371605519'}];
test('triagem61 conserva identidade operação e idempotência',()=>{for(const r of rows){const p={...r,preco:'salvo',historico:'preservado',linkAfiliado:'https://meli.la/preservar',variation_id:'123'},x=correctProductData(p);for(const k of Object.keys(p).filter(k=>k!=='titulo'))assert.deepEqual(x[k],p[k]);assert.deepEqual(correctProductData(x),x);for(const alt of [{id:'outro'},{titulo:'Capa para '+r.titulo},{link:'https://www.mercadolivre.com.br/p/MLB12345678?wid=MLB9999999999'}])assert.equal(correctProductData({...p,comentario:'preservar',...alt}).comentario,'preservar');assert.ok(x.titulo.length<=100);}});
test('Growth não mantém recomendação alimentar como instrução nem pureza certificada',()=>{const x=correctProductData(rows[0]);assert.match(x.comentario,/não foi confirmada nesta revisão/);assert.match(x.comentario,/não prescreve consumo/);assert.doesNotMatch(x.titulo,/100%/);assert.doesNotMatch(x.pros,/glúten|pura|assimilação|ideal|dose/i);});
test('colágeno distingue cápsulas de doses e não presume fórmula específica',()=>{const x=correctProductData(rows[1]);assert.match(x.comentario,/não garantem 60 doses ou 60 dias/);assert.match(x.comentario,/o título sozinho não esclarece/);assert.match(x.titulo,/45 mg anunciados/);assert.doesNotMatch(x.pros,/biodisponibilidade|UC-II|não desnaturado|dose|articula/i);});
test('Rishon não garante choque térmico ou conservação nem muda identidade do kit',()=>{const x=correctProductData(rows[2]);assert.equal(x.titulo,rows[2].titulo);assert.match(x.comentario,/Não presumimos resistência a choque térmico/);assert.match(x.comentario,/recipiente e da tampa/);assert.doesNotMatch(x.pros,/borossilicato|garant|seguran|micro-ondas|lava-louças|resisten/i);});
